from pathlib import Path
items=json.loads(Path('_inventory_envs_fresh.json').read_text(encoding='utf-8'))

def labels_between(start,end):
    return '; '.join(i['label'] for i in items if i['file']=='main.tex' and start <= i['line'] <= end and i['label'])

def row(label, location, reason, required_action, **extra):
    d={"label":label,"location":location,"reason":reason,"required_action":required_action}
    d.update(extra)
    return d

