md=['# Theorem Inventory\n','Stage A theorem inventory for `2026_auditable_theory_to_paper_pipeline`. This inventory is scope-bound to the stable scope files, manuscript sources, bibliography, and named support bundle records.\n']
for k in keys:
    if k=='valid':
        md += ['## valid\n', '`true`\n']
        continue
    md.append('## '+k.replace('_',' ').title()+'\n')
    if not inv[k]:
        md.append('- None recorded.\n')
        continue
    for it in inv[k]:
        md.append(f"- **{it['label']}** (`{it['location']}`): {it['reason']} Required action: {it['required_action']}")
        if k in ('out_of_scope_strong_results','split_candidates'):
            for extra in ('candidate_title','source_contribution','scope_mismatch','independent_paper_rationale'):
                if extra in it:
                    md.append(f"  - {extra.replace('_',' ')}: {it[extra]}")
            if 'needed_to_split' in it:
                md.append('  - needed to split: '+'; '.join(it['needed_to_split']))
        md.append('')
    md.append('')
Path('theorem_inventory.md').write_text('\n'.join(md),encoding='utf-8')
print('wrote theorem_inventory.json and theorem_inventory.md')
